from lib import *
S = SS('g48')
steps = [
    step("GOMAXPROCS=1,一个 goroutine 进入阻塞的系统调用(syscall.Syscall6,会通知运行时),同时有另一个 goroutine 等着运行。另一个 goroutine 开始运行的延迟(20 次的最小/中位/最大):系统调用阻塞 100 µs:42 / 45 / 62 µs;1000 µs:10 / 13 / 156 µs;10000 µs:10 / 41 / 97 µs;100000 µs:6 / 65 / 223 µs。即使系统调用要阻塞 100 ms,另一个 goroutine 也只等了约 65 µs——P 很快被从阻塞的系统调用里拿走交给别人。(系统调用本身的耗时比请求的更长,如 1000 µs 的请求中位 1511 µs,这是 macOS 上 select 超时的表现,与运行时无关。)", t=tl(S(1)), done=lidx(S(1), '阻塞    100 µs', '阻塞   1000 µs'), mark=lidx(S(1), '阻塞  10000 µs', '阻塞 100000 µs'), b=bars([['阻塞 100 µs:等待(µs)', 45, '45'], ['1000 µs', 13, '13'], ['10000 µs', 41, '41'], ['100000 µs', 65, '65']], 65, done=[0, 1], mark=[2, 3]), kv=KV([['等待 P 的延迟(中位)', '45 / 13 / 41 / 65 µs,与系统调用多长无关'], ['含义', '阻塞的系统调用不会让其它 goroutine 饿死']], ['含义'])),
    step("绕开运行时的系统调用(syscall.RawSyscall6,不通知运行时):另一个 goroutine 一直等到系统调用结束。延迟中位 145、1512、14989、29988 µs,与各自系统调用本身的耗时(144、1511、14987、29989 µs)几乎相同——P 没有被移交。(100 ms 那一行系统调用只花了约 30 ms 就返回了,我猜是被运行时的抢占信号打断,没有验证。)", t=tl(S(2)), done=lidx(S(2), '阻塞    100 µs'), mark=lidx(S(2), '阻塞  10000 µs', '阻塞 100000 µs'), b=bars([['Syscall6:等待 P(µs,1000µs 调用)', 13, '13'], ['RawSyscall6(同样 1000 µs)', 1512, '1512'], ['Syscall6(10000 µs)', 41, '41'], ['RawSyscall6(10000 µs)', 14989, '14989']], 14989, done=[0, 2], mark=[1, 3]), kv=KV([['Syscall6', '另一个 goroutine 等 13–65 µs'], ['RawSyscall6', '等到系统调用返回:145 µs / 1512 µs / 14989 µs'], ['原因', 'Raw 版本不通知运行时,P 一直留在这个线程上']], ['原因'])),
    step("同样的负载,GOMAXPROCS=4(有空闲的 P):另一个 goroutine 开始运行的延迟中位 4、6、10、36 µs(系统调用 100、1000、10000、100000 µs),比只有 1 个 P 时更短——不用等 sysmon 来拿走 P,空闲的 P 直接就能被唤醒去运行它。", t=tl(S(3)), done=lidx(S(3), '阻塞    100 µs'), mark=lidx(S(3), '阻塞 100000 µs'), b=bars([['P=1(1000 µs 调用)', 13, '13'], ['P=4(同样 1000 µs 调用)', 6, '6'], ['P=1(100000 µs)', 65, '65'], ['P=4(100000 µs)', 36, '36']], 65, done=[1, 3], mark=[0, 2]), kv=KV([['P=4', '4 / 6 / 10 / 36 µs'], ['P=1', '45 / 13 / 41 / 65 µs'], ['原因', '有空闲 P 时直接唤醒它,不依赖 sysmon 从阻塞中拿 P(这是我对差异的解释)']], ['原因'])),
    step("运行时源码(runtime/proc.go)里 sysmon 与 retake:sysmon 的睡眠间隔 delay 在“空闲计数为 0”时设为 20 µs,空闲超过 50 轮(约 1 ms)后每轮翻倍,上限 10 ms,然后 usleep(delay)。retake 里注释写着:Retake the P if it's there for more than 1 sysmon tick (at least 20us)——如果 P 在系统调用里停留超过一个 sysmon 周期(至少 20 µs),就拿走;但如果本地运行队列为空、还有空闲或自旋的 P 且停留不到 10 ms,就先不拿(We don't want to retake Ps if there is no other work to do,但最终会拿,因为它们会让 sysmon 无法深睡);拿走后注释写着 Handoff the P for some other thread to run it(代码里调用 handoffp,摘录没有包含那一行)。", t=tl(S(4)), done=lidx(S(4), 'delay = 20', 'delay *= 2', 'delay = 10 * 1000'), mark=lidx(S(4), 'Retake the P if', 'runqempty(pp)', 'Handoff the P'), kv=KV([['sysmon 周期', '20 µs 起,空闲超过 50 轮后翻倍,最长 10 ms'], ['拿走条件', 'P 在系统调用里超过 1 个 sysmon 周期(≥ 20 µs),且有别的活要做'], ['没活做时', '最多拖到 10 ms 再拿'], ['拿走之后', 'handoffp:交给别的线程运行']], ['拿走条件'])),
]
A = mkartg('g48', 48, 'Go,调度器,系统调用,sysmon,handoff,真实验证,动画演示',
    '在 Go 1.27.1 里测系统调用阻塞时 P 的移交:只有 1 个 P 时,一个 goroutine 阻塞在 syscall.Syscall6 的系统调用里(哪怕长达 100 ms),另一个 goroutine 只等 13–65 µs 就拿到 P;改用不通知运行时的 RawSyscall6,另一个 goroutine 要等到系统调用结束;有空闲 P 时等待更短(4–36 µs);并摘录 sysmon 的 20 µs 起步、至多 10 ms 的睡眠间隔与 retake 的条件。',
    '一个 goroutine 阻塞在系统调用里,它占着的 P 怎么办?如果 P 也跟着停了,其它 goroutine 就饿死了。这篇用只有一个 P 的最苛刻设置量出被饿的时间,再用不通知运行时的原始系统调用做对照,并读源码里 sysmon 拿走 P 的规则。',
    [('≈ 65 µs', 'GOMAXPROCS=1 时,即使系统调用阻塞 100 ms,另一个 goroutine 也只等这么久就拿到 P'), ('RawSyscall', '不通知运行时的系统调用不移交 P:另一个 goroutine 要等到它返回'), ('20 µs', 'sysmon 睡眠间隔的起点,retake 要求 P 在系统调用里至少停留一个周期')],
    [('阻塞的系统调用会让出 P', '<p><code>syscall.Syscall6</code> 进入内核前先告诉运行时“我要进系统调用了”(<code>entersyscall</code>);运行时的监控线程 <code>sysmon</code> 发现这个 P 在系统调用里超过一个周期且有别的 goroutine 在等,就把 P 拿走交给别的线程。实验里这个交接只需几十微秒,所以只有一个 P 时,另一个 goroutine 也不会饿死。</p>'),
     ('不通知运行时就没有交接', '<p><code>RawSyscall</code> 不调用 <code>entersyscall</code>,运行时认为这个 goroutine 一直在运行用户代码,P 不会被拿走,另一个 goroutine 只能等它返回——延迟与系统调用时长几乎一样。这就是为什么只有确定几乎立刻返回的系统调用才适合用 raw 版本。</p>'),
     ('有空闲 P 时更快', '<p>GOMAXPROCS=4 时有空闲的 P,等待的 goroutine 几乎立刻被唤醒去跑(4–36 µs),不必等 sysmon 从阻塞的线程手里拿走 P。这个差异我是从现象推的,没有读唤醒路径的代码。</p>'),
     ('sysmon 的节奏', '<p>源码里 sysmon 在忙的时候每 20 µs 看一次,空闲久了逐渐拉长到 10 ms;retake 的规则是 P 在系统调用里停留超过一个周期才可能被拿走,并且如果没有别的活可干,最长可以拖到 10 ms 才拿。这解释了为什么实验里等待延迟是几十微秒,而不是 10 ms——因为有一个等着运行的 goroutine。</p>')],
    steps,
    [ENV_G + '。系统调用用 select(0, nil, nil, nil, &timeval) 在 macOS 上阻塞(超时精度本身比请求的粗,如 1000 µs 的请求耗时约 1511 µs);每个设置 20 次取最小/中位/最大;“另一个 goroutine”只是记录自己开始运行的时间;读过的源码:runtime/proc.go 的 sysmon 开头与 retake 的一段',
     '没有验证:Linux 上的延迟、systemcall 时间极短时(< 20 µs)的行为、handoffp 的完整流程、RawSyscall 被抢占信号打断的细节(100 ms 那一行提前返回的原因)、cgo 调用与 Syscall 在移交上的异同、sysmon 睡眠间隔随负载变化的实测'],
    '系统调用与 P 的移交')
